// NewQTimeLineWith constructs a QTimeLine whose virtual methods dispatch to v. The
// object holds v for as long as it lives, so v's Go state survives even when
// only Qt refers to it: through its window's handle, or pinned (Delete it when
// done) if it has no parent.
func NewQTimeLineWith(v QTimeLineSubclass, duration int, parent QObjectLike) *QTimeLine {
	rt.CheckThread("NewQTimeLineWith")
	base := v.quteQTimeLineBase()
	if base.QTimeLine != nil {
		panic("NewQTimeLineWith: value is already constructed; use a fresh value")
	}
	var parentPtr unsafe.Pointer
	if parent != nil {
		parentPtr = rt.UseArg(unsafe.Pointer(parent.AsQObject()), "NewQTimeLineWith")
	}
	p := C.qute_QTimeLine_new_shim(C.int(duration), parentPtr)
	runtime.KeepAlive(parent)
	mode := rt.NewOwned
	if parentPtr != nil {
		mode = rt.NewParented
	}
	h := rt.WrapNewShim[QTimeLine](p, "QTimeLine", mode, qTimeLineVTable, qTimeLineShimInit)
	base.QTimeLine = rt.View[QTimeLine](h, p)
	id := h.SetSelf(v, qTimeLineVTable)
	mask := rt.Mask(v, qTimeLineVTable)
	if len(mask) == 0 {
		mask = []uint64{0}
	}
	C.qute_QTimeLine_shim_init(p, C.uintptr_t(id), (*C.uint64_t)(unsafe.Pointer(&mask[0])))
	return base.QTimeLine
}
